package com.aurasound.next;
import android.app.*;import android.content.*;import android.media.*;import android.media.audiofx.Equalizer;import android.media.audiofx.AudioEffect;import android.media.audiofx.Visualizer;import android.media.audiofx.LoudnessEnhancer;import android.media.session.MediaSession;import android.media.session.PlaybackState;import android.media.MediaMetadata;import android.net.Uri;import android.os.*;import org.json.*;
public class PlaybackService extends Service{
 public static final String ACTION_SEEK="com.aurasound.next.SEEK",ACTION_VISUALIZER_REFRESH="com.aurasound.next.VISUALIZER_REFRESH",ACTION_EQ_BAND="com.aurasound.next.EQ_BAND",ACTION_EQ_BASS="com.aurasound.next.EQ_BASS",ACTION_EQ_TREBLE="com.aurasound.next.EQ_TREBLE",ACTION_EQ_AMP="com.aurasound.next.EQ_AMP",ACTION_EQ_RESET="com.aurasound.next.EQ_RESET"; public static final String ACTION_SET_QUEUE="com.aurasound.next.SET_QUEUE",ACTION_TOGGLE="com.aurasound.next.TOGGLE",ACTION_NEXT="com.aurasound.next.NEXT",ACTION_PREVIOUS="com.aurasound.next.PREVIOUS",ACTION_STATE="com.aurasound.next.STATE";
 private static final String CHANNEL="aurasound_playback";private static final int NOTIFICATION=77;private MediaPlayer player;private MediaSession session;private Equalizer equalizer;private Visualizer visualizer;private LoudnessEnhancer loudness;private final int[] uiEqLevels=new int[10];private int bassDb=2,trebleDb=0;private final Handler handler=new Handler(Looper.getMainLooper());private final Runnable ticker=new Runnable(){public void run(){if(player!=null){publish();handler.postDelayed(this,500);}}};private final java.util.ArrayList<Track> queue=new java.util.ArrayList<>();private int index=-1;private boolean wantsPlay=false;private boolean prepared=false;private int pendingSeek=-1;
 private static class Track{String uri,title,artist;int originalIndex;Track(String u,String t,String a,int o){uri=u;title=t;artist=a;originalIndex=o;}}
 @Override public void onCreate(){super.onCreate();createChannel();session=new MediaSession(this,"AuraSoundSession");session.setCallback(new MediaSession.Callback(){@Override public void onPlay(){play();}@Override public void onPause(){pause();}@Override public void onSkipToNext(){next(1);}@Override public void onSkipToPrevious(){next(-1);}@Override public void onStop(){pause();stopForeground(true);}});session.setFlags(MediaSession.FLAG_HANDLES_MEDIA_BUTTONS|MediaSession.FLAG_HANDLES_TRANSPORT_CONTROLS);session.setActive(true);}
 @Override public int onStartCommand(Intent intent,int flags,int startId){if(intent==null)return START_STICKY;String a=intent.getAction();if(ACTION_SET_QUEUE.equals(a))loadQueue(intent.getStringExtra("queue"),intent.getIntExtra("index",0),intent.getBooleanExtra("autoplay",true));else if(ACTION_TOGGLE.equals(a)){if(player!=null&&player.isPlaying())pause();else play();}else if(ACTION_NEXT.equals(a))next(1);else if(ACTION_PREVIOUS.equals(a))next(-1);else if(ACTION_SEEK.equals(a)){seekTo(intent.getIntExtra("position",0));}else if(ACTION_VISUALIZER_REFRESH.equals(a)){attachVisualizer();}else if(ACTION_EQ_BAND.equals(a))setEqFrequency(intent.getIntExtra("band",-1),intent.getIntExtra("level",0));else if(ACTION_EQ_BASS.equals(a))setEqBass(intent.getIntExtra("level",3));else if(ACTION_EQ_TREBLE.equals(a))setEqTreble(intent.getIntExtra("level",0));else if(ACTION_EQ_AMP.equals(a))setEqAmp(intent.getFloatExtra("level",1f));else if(ACTION_EQ_RESET.equals(a))resetEq();return START_STICKY;}
 private void loadQueue(String json,int selected,boolean autoplay){queue.clear();try{JSONArray a=new JSONArray(json);for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);String u=o.optString("url");if(u.startsWith("content:"))queue.add(new Track(u,o.optString("name","آهنگ"),o.optString("artist",o.optString("album","")),o.optInt("originalIndex",i)));}}catch(Exception ignored){}if(queue.isEmpty()){stopSelf();return;}index=Math.max(0,Math.min(selected,queue.size()-1));wantsPlay=autoplay;startForeground(NOTIFICATION,notification());prepare();}
 private void prepare(){releasePlayer();if(index<0||index>=queue.size())return;Track t=queue.get(index);player=new MediaPlayer();try{player.setWakeMode(this,PowerManager.PARTIAL_WAKE_LOCK);player.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build());player.setDataSource(this,Uri.parse(t.uri));player.setOnPreparedListener(mp->{prepared=true;attachEffects(mp.getAudioSessionId());if(pendingSeek>=0){try{mp.seekTo(Math.min(pendingSeek,Math.max(0,mp.getDuration())));}catch(Exception ignored){}pendingSeek=-1;}if(wantsPlay){mp.start();updateSession(PlaybackState.STATE_PLAYING);}else updateSession(PlaybackState.STATE_PAUSED);updateMetadata();refreshNotification();publish();handler.removeCallbacks(ticker);handler.post(ticker);});player.setOnSeekCompleteListener(mp->publish());player.setOnCompletionListener(mp->next(1));player.setOnErrorListener((mp,w,e)->{publish();return true;});player.prepareAsync();updateMetadata();publish();}catch(Exception e){publish();}}
 private void attachEffects(int id){releaseEffects();try{final Equalizer eq=new Equalizer(1000,id);equalizer=eq;eq.setControlStatusListener((effect,granted)->{if(granted)handler.post(()->{if(equalizer==eq){try{eq.setEnabled(true);applyEqualizer();}catch(Exception ignored){}}});});eq.setEnableStatusListener((effect,enabled)->{if(!enabled)handler.post(()->{if(equalizer==eq&&eq.hasControl()){try{eq.setEnabled(true);applyEqualizer();}catch(Exception ignored){}}});});eq.setEnabled(true);resetEq();}catch(Exception e){equalizer=null;}attachVisualizer();}
 private void attachVisualizer(){releaseVisualizer();try{if(player==null||!prepared)return;visualizer=new Visualizer(player.getAudioSessionId());visualizer.setCaptureSize(Visualizer.getCaptureSizeRange()[1]);visualizer.setDataCaptureListener(new Visualizer.OnDataCaptureListener(){public void onWaveFormDataCapture(Visualizer v,byte[] d,int r){}public void onFftDataCapture(Visualizer v,byte[] d,int r){sendBroadcast(new Intent(ACTION_STATE).setPackage(getPackageName()).putExtra("fft",d));}},Math.min(20000,Visualizer.getMaxCaptureRate()),false,true);visualizer.setEnabled(true);}catch(Exception e){releaseVisualizer();}}
 private void releaseVisualizer(){if(visualizer!=null){try{visualizer.setEnabled(false);visualizer.release();}catch(Exception e){}visualizer=null;}}
 private void releaseEffects(){releaseVisualizer();if(equalizer!=null){try{equalizer.setEnabled(false);equalizer.release();}catch(Exception e){}equalizer=null;}if(loudness!=null){try{loudness.setEnabled(false);loudness.release();}catch(Exception e){}loudness=null;}}
 private void setEqFrequency(int i,int db){if(i<0||i>=uiEqLevels.length)return;uiEqLevels[i]=Math.max(-12,Math.min(12,db));applyEqualizer();}
 private int bandHz(short b){return equalizer.getCenterFreq(b)/1000;}
 private int nearestBandIndex(int hz){int best=0,delta=Integer.MAX_VALUE;for(short b=0;b<equalizer.getNumberOfBands();b++){int d=Math.abs(bandHz(b)-hz);if(d<delta){delta=d;best=b;}}return best;}
 private void applyEqualizer(){try{if(equalizer==null||!equalizer.hasControl())return;equalizer.setEnabled(true);int[] f={31,62,125,250,500,1000,2000,4000,8000,16000};int countBands=equalizer.getNumberOfBands();int[] sums=new int[countBands],counts=new int[countBands];for(int i=0;i<f.length;i++){int b=nearestBandIndex(f[i]);sums[b]+=uiEqLevels[i];counts[b]++;}for(short b=0;b<countBands;b++){int hz=bandHz(b);double ui=counts[b]==0?0:(double)sums[b]/counts[b];double low=hz<=80?1.0:hz<=160?0.75:hz<=320?0.4:0;double high=hz>=8000?1.0:hz>=4000?0.75:hz>=2000?0.4:0;setBand(b,(int)Math.round(ui+bassDb*low+trebleDb*high));}}catch(Exception e){}}
 private void setBand(int b,int db){try{if(equalizer==null||b<0||b>=equalizer.getNumberOfBands())return;short[] r=equalizer.getBandLevelRange();equalizer.setBandLevel((short)b,(short)Math.max(r[0],Math.min(r[1],db*100)));}catch(Exception e){}}
 private void setEqBass(int db){bassDb=Math.max(-8,Math.min(10,(int)Math.round(db*0.65)));applyEqualizer();}
 private void setEqTreble(int db){trebleDb=Math.max(-12,Math.min(12,db));applyEqualizer();}
 private void setEqAmp(float multiplier){try{if(loudness==null&&player!=null)loudness=new LoudnessEnhancer(player.getAudioSessionId());if(loudness!=null){float safe=Math.max(0.5f,Math.min(4f,multiplier));int gainMb=(int)Math.round(2000.0*Math.log10(safe));loudness.setTargetGain(gainMb);loudness.setEnabled(true);}}catch(Exception e){}}
 private void resetEq(){java.util.Arrays.fill(uiEqLevels,0);bassDb=2;trebleDb=0;applyEqualizer();setEqAmp(1f);}
 private void play(){if(player==null){if(!queue.isEmpty())prepare();return;}wantsPlay=true;try{if(!player.isPlaying())player.start();updateSession(PlaybackState.STATE_PLAYING);refreshNotification();publish();}catch(Exception ignored){}}
 private void pause(){wantsPlay=false;try{if(player!=null&&player.isPlaying())player.pause();}catch(Exception ignored){}updateSession(PlaybackState.STATE_PAUSED);refreshNotification();publish();}
 private void next(int d){if(queue.isEmpty())return;index=(index+d+queue.size())%queue.size();wantsPlay=true;prepare();}
 private void updateMetadata(){if(session==null||queue.isEmpty())return;Track t=queue.get(index);long duration=0;try{if(player!=null)duration=player.getDuration();}catch(Exception ignored){}session.setMetadata(new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,t.title).putString(MediaMetadata.METADATA_KEY_ARTIST,t.artist).putLong(MediaMetadata.METADATA_KEY_DURATION,duration).build());}
 private void updateSession(int state){if(session==null)return;long actions=PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE|PlaybackState.ACTION_PLAY_PAUSE|PlaybackState.ACTION_SKIP_TO_NEXT|PlaybackState.ACTION_SKIP_TO_PREVIOUS|PlaybackState.ACTION_STOP;long pos=0;try{if(player!=null)pos=player.getCurrentPosition();}catch(Exception ignored){}session.setPlaybackState(new PlaybackState.Builder().setActions(actions).setState(state,pos,state==PlaybackState.STATE_PLAYING?1:0).build());}
 private void publish(){if(queue.isEmpty()||index<0||index>=queue.size())return;Track t=queue.get(index);int pos=0,dur=0;try{if(player!=null){pos=player.getCurrentPosition();dur=player.getDuration();}}catch(Exception e){}Intent i=new Intent(ACTION_STATE).setPackage(getPackageName()).putExtra("index",t.originalIndex).putExtra("playing",player!=null&&player.isPlaying()).putExtra("title",t.title).putExtra("artist",t.artist).putExtra("position",pos).putExtra("duration",dur);sendBroadcast(i);updateSession(player!=null&&player.isPlaying()?PlaybackState.STATE_PLAYING:PlaybackState.STATE_PAUSED);}
 private void refreshNotification(){try{((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(NOTIFICATION,notification());}catch(Exception ignored){}}
 private Notification notification(){Track t=queue.isEmpty()?new Track("","","AuraSound",0):queue.get(Math.max(0,Math.min(index,queue.size()-1)));PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);boolean p=player!=null&&player.isPlaying();Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,CHANNEL):new Notification.Builder(this);b.setSmallIcon(android.R.drawable.ic_media_play).setContentTitle(t.title).setContentText(t.artist).setContentIntent(open).setOngoing(p).setVisibility(Notification.VISIBILITY_PUBLIC).addAction(action(android.R.drawable.ic_media_previous,"قبلی",ACTION_PREVIOUS,1)).addAction(action(p?android.R.drawable.ic_media_pause:android.R.drawable.ic_media_play,p?"مکث":"پخش",ACTION_TOGGLE,2)).addAction(action(android.R.drawable.ic_media_next,"بعدی",ACTION_NEXT,3));if(Build.VERSION.SDK_INT>=21)b.setStyle(new Notification.MediaStyle().setMediaSession(session.getSessionToken()).setShowActionsInCompactView(0,1,2));return b.build();}
 private Notification.Action action(int icon,String title,String action,int id){PendingIntent pi=PendingIntent.getService(this,id,new Intent(this,PlaybackService.class).setAction(action),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);return new Notification.Action.Builder(icon,title,pi).build();}
 private void createChannel(){if(Build.VERSION.SDK_INT>=26){NotificationChannel c=new NotificationChannel(CHANNEL,"پخش موسیقی",NotificationManager.IMPORTANCE_LOW);c.setDescription("کنترل پخش موسیقی AuraSound");((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(c);}}
 private void seekTo(int position){int target=Math.max(0,position);if(player==null||!prepared){pendingSeek=target;return;}try{target=Math.min(target,Math.max(0,player.getDuration()));player.seekTo(target);publish();}catch(Exception ignored){pendingSeek=target;}}
 private void releasePlayer(){handler.removeCallbacks(ticker);prepared=false;pendingSeek=-1;releaseEffects();if(player!=null){try{player.reset();player.release();}catch(Exception ignored){}player=null;}}
 @Override public void onDestroy(){releasePlayer();if(session!=null){session.setActive(false);session.release();}super.onDestroy();}
 @Override public android.os.IBinder onBind(Intent i){return null;}
}